package in.kalaimarket;
import java.time.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class PnlLedgerTest {
 BrokerDeal deal(long ticket,String utc,String profit,String commission){var d=new BrokerDeal();d.ticket=ticket;d.tradedAt=Instant.parse(utc);d.profit=new BigDecimal(profit);d.commission=new BigDecimal(commission);d.swap=new BigDecimal("-0.1");d.fee=new BigDecimal("-0.01");d.dealType=1;d.entryKind=1;return d;}
 @Test void dailyNetIncludesCostsAndUsesChennaiDateBoundary(){var execution=mock(DemoExecutionService.class);when(execution.getAccount()).thenReturn(123456L);when(execution.getServer()).thenReturn("OctaFX-Demo");var deals=mock(BrokerDealRepository.class);var sync=mock(BrokerSyncRepository.class);var rows=List.of(deal(1,"2026-10-11T18:40:00Z","3","-0.2"),deal(2,"2026-10-12T18:29:00Z","-1","-0.2"));when(deals.findByAccountLoginAndBrokerServerAndTradedAtGreaterThanEqualAndTradedAtLessThanOrderByTradedAtAsc(anyLong(),anyString(),any(),any())).thenReturn(rows);var api=new PnlController(execution,deals,sync,mock(BrokerExecutionRepository.class),mock(AutoSignalRepository.class),mock(ExecutionEventRepository.class));var out=api.pnl("Asia/Kolkata",LocalDate.parse("2026-10-12"),LocalDate.parse("2026-10-12"),"ACCOUNT");var total=(PnlController.Day)out.get("total");assertEquals(0,new BigDecimal("1.38").compareTo(total.getNet()));assertEquals(2,total.exitDeals);verify(deals).findByAccountLoginAndBrokerServerAndTradedAtGreaterThanEqualAndTradedAtLessThanOrderByTradedAtAsc(123456L,"OctaFX-Demo",Instant.parse("2026-10-11T18:30:00Z"),Instant.parse("2026-10-12T18:30:00Z"));}
 @Test void kmrScopeExcludesUnlinkedBrokerTrades(){var e=mock(DemoExecutionService.class);when(e.getServer()).thenReturn("OctaFX-Demo");var d=mock(BrokerDealRepository.class);var rows=List.of(deal(1,"2026-10-12T12:00:00Z","3","-0.2"));when(d.findByAccountLoginAndBrokerServerAndTradedAtGreaterThanEqualAndTradedAtLessThanOrderByTradedAtAsc(anyLong(),anyString(),any(),any())).thenReturn(rows);var api=new PnlController(e,d,mock(BrokerSyncRepository.class),mock(BrokerExecutionRepository.class),mock(AutoSignalRepository.class),mock(ExecutionEventRepository.class));assertEquals(BigDecimal.ZERO,((PnlController.Day)api.pnl("Asia/Kolkata",LocalDate.now(),LocalDate.now(),"KMR").get("total")).getNet());}
}
